function [graded] = gyro_graded(fine, grade)
%GYRO_GRADED  Whether the precision gyro is graded: on the fine class, when the loop's grade is below 0.999.
%   fine: bool (passed true or false)
%   grade: real[1] (passed a plain number)
%   returns graded: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    graded = false;
    graded = (fine && (grade < 0.999));
end
